def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_d = 0
    opp_c = 0
    my_d = 0
    for i in range(n):
        if opp[i] == 'D':
            opp_d += 1
        else:
            opp_c += 1
        if me[i] == 'D':
            my_d += 1

    last_me = me[-1]
    last_opp = opp[-1]
    remaining = 100 - n

    recent_n = 8 if n >= 8 else n
    recent_d = 0
    for i in range(n - recent_n, n):
        if opp[i] == 'D':
            recent_d += 1

    opp_rate = opp_c / n

    if remaining <= 1:
        return 'D'

    if n >= 6 and opp_d == 0:
        if remaining <= 3:
            return 'D'
        return 'C'

    if n >= 6 and opp_c == 0:
        return 'D'

    if remaining <= 4:
        if recent_d == 0 and opp_rate > 0.6:
            return 'C'
        return 'D'

    if recent_d >= recent_n - 1 and n >= 4:
        return 'D'

    if recent_d * 2 > recent_n:
        if opp_rate < 0.35:
            return 'D'
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    if n >= 10:
        if opp_rate < 0.25:
            if rng.random() < 0.9:
                return 'D'
            return 'C'
        if opp_rate > 0.9 and recent_d == 0:
            if n % 11 == 0 and remaining > 10:
                return 'D'
            return 'C'

    if last_opp == 'D':
        if recent_d >= 2:
            return 'D'
        if last_me == 'D':
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    if last_me == 'D' and last_opp == 'C':
        if n >= 12 and opp_rate > 0.65 and rng.random() < 0.5:
            return 'D'
        return 'C'

    if n >= 12 and opp_rate < 0.45 and recent_d >= 1:
        if rng.random() < 0.4:
            return 'D'

    return 'C'
